```json
{
  "root_causes": [
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, attr_k8s_pod_name AS pod, count(*) n, min(value) v_min, max(value) v_max FROM abnormal_metrics WHERE metric IN ('k8s.container.ready','k8s.deployment.available','k8s.container.restarts') AND (attr_k8s_pod_name LIKE 'profile%' OR service_name='profile') GROUP BY ALL ORDER BY 1,2,3",
          "claim": "Profile container stayed not ready and deployment available=0 through the abnormal window, with restarts rising to 6."
        },
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) err FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE span_name LIKE 'profile.%' OR service_name='profile' GROUP BY ALL ORDER BY 1,2,3",
          "claim": "Profile server spans vanish in the abnormal period; frontend's profile.GetProfiles calls all error (856 of 856, vs 0 of 938 normal)."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n, min(time) first_t FROM abnormal_logs WHERE service_name='frontend' AND level='ERROR' GROUP BY ALL",
          "claim": "Frontend logs 607 ERROR entries 'Get profiles failed' starting shortly after the abnormal window begins."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT t.service_name, t.span_name, t.attr_span_kind, t.attr_status_code, t.attr_http_response_status_code, count(*) n FROM abnormal_traces t WHERE t.service_name='frontend' AND (t.span_name LIKE 'profile.%' OR t.span_name IN ('HTTP /hotels','HTTP /recommendations')) GROUP BY ALL ORDER BY 2,3",
          "claim": "Frontend's profile calls fail, and the user-facing /hotels and /recommendations routes return HTTP 500 for every request."
        }
      ]
    }
  ]
}
```

